SELECT "agencyid", "sk_recorddateid", "sk_updatedateid", "batchid", "iscustomer", "lastname", "firstname", "middleinitial", "gender", "addressline1", "addressline2", "postalcode", "city", "state", "country", "phone", "income", "numbercars", "numberchildren", "maritalstatus", "age", "creditrating", "ownorrentflag", "employer", "numbercreditcards", "networth", "marketingnameplate" FROM (SELECT TRY_CAST((CAST(p.AgencyID AS CHAR(30))) AS char(30)) AS "agencyid", TRY_CAST((CAST(20170707 AS INTEGER)) AS int) AS "sk_recorddateid", TRY_CAST((CAST(NULL AS INTEGER)) AS int) AS "sk_updatedateid", TRY_CAST((CAST(NULL AS DECIMAL(5))) AS decimal(5)) AS "batchid", TRY_CAST((FALSE) AS boolean) AS "iscustomer", TRY_CAST((CAST(p.LastName AS CHAR(30))) AS char(30)) AS "lastname", TRY_CAST((CAST(p.FirstName AS CHAR(30))) AS char(30)) AS "firstname", TRY_CAST((CAST(p.MiddleInitial AS CHAR(1))) AS char(1)) AS "middleinitial", TRY_CAST((CASE WHEN p.Gender IS NULL THEN NULL WHEN UPPER(p.Gender) = 'M' THEN 'M' WHEN UPPER(p.Gender) = 'F' THEN 'F' ELSE 'U' END) AS char(1)) AS "gender", TRY_CAST((CAST(p.AddressLine1 AS CHAR(80))) AS char(80)) AS "addressline1", TRY_CAST((p.AddressLine2) AS char(80)) AS "addressline2", TRY_CAST((CAST(p.PostalCode AS CHAR(12))) AS char(12)) AS "postalcode", TRY_CAST((CAST(p.City AS CHAR(25))) AS char(25)) AS "city", TRY_CAST((CAST(p.State AS CHAR(20))) AS char(20)) AS "state", TRY_CAST((CAST(p.Country AS CHAR(24))) AS char(24)) AS "country", TRY_CAST((CAST(p.Phone AS CHAR(30))) AS char(30)) AS "phone", TRY_CAST((p.Income) AS decimal(9)) AS "income", TRY_CAST((p.NumberCars) AS decimal(2)) AS "numbercars", TRY_CAST((p.NumberChildren) AS decimal(2)) AS "numberchildren", TRY_CAST((p.MaritalStatus) AS char(1)) AS "maritalstatus", TRY_CAST((p.Age) AS decimal(3)) AS "age", TRY_CAST((p.CreditRating) AS decimal(4)) AS "creditrating", TRY_CAST((p."OwnOrRentFlag") AS char(1)) AS "ownorrentflag", TRY_CAST((CAST(p.Employer AS CHAR(30))) AS char(30)) AS "employer", TRY_CAST((p.NumberCreditCards) AS decimal(2)) AS "numbercreditcards", TRY_CAST((p.NetWorth) AS decimal(12)) AS "networth", TRY_CAST((CAST(NULL AS CHAR(100))) AS char(100)) AS "marketingnameplate" FROM Prospect p)
